#!/usr/bin/env bash\n# Release gates backed by PostgreSQL metadata. Presence-only checks are not sufficient.\nset -euo pipefail\n\nPGHOST="${PGHOST:-localhost}"\nPGPORT="${PGPORT:-5432}"\nPGUSER="${PGUSER:-postgres}"\nPGDATABASE="${PGDATABASE:-construction}"\nPSQL=(psql -X -v ON_ERROR_STOP=1 -h "$PGHOST" -p "$PGPORT" -U "$PGUSER" -d "$PGDATABASE" -t -A)\n\nif ! command -v psql >/dev/null 2>&1; then\n  echo "BLOCKED: psql no está instalado; no se pueden verificar gates de BD."\n  exit 2\nfi\nif ! "${PSQL[@]}" -c 'SELECT 1' >/dev/null 2>&1; then\n  echo "BLOCKED: no se pudo conectar a $PGHOST:$PGPORT/$PGDATABASE como $PGUSER."\n  exit 2\nfi\n\nfail=0\ncheck() {\n  local name="$1" query="$2" expected="$3" actual\n  if actual=$("${PSQL[@]}" -c "$query" 2>/dev/null); then :; else actual="ERR"; fi\n  actual="$(printf '%s' "$actual" | tr -d '[:space:]')"\n  if [[ "$actual" == "$expected" ]]; then\n    echo "  PASS | $name"\n  else\n    echo "  FAIL | $name | esperado=$expected obtenido=$actual"\n    fail=1\n  fi\n}\n\necho "Gates release DB=$PGDATABASE host=$PGHOST:$PGPORT user=$PGUSER"\n\ncheck "schema public: audit_event existe" \\n  "SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name='audit_event'" "1"\ncheck "schema public: projection_outbox existe" \\n  "SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name='projection_outbox'" "1"\ncheck "app_user existe" \\n  "SELECT count(*) FROM pg_roles WHERE rolname='app_user'" "1"\ncheck "app_user sin SUPERUSER/BYPASSRLS/CREATEROLE/CREATEDB" \\n  "SELECT count(*) FROM pg_roles WHERE rolname='app_user' AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb" "1"\ncheck "app_user no es owner de tablas públicas" \\n  "SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='public' AND c.relkind IN ('r','p') AND r.rolname='app_user'" "0"\ncheck "app_user no puede borrar projection_outbox" \\n  "SELECT has_table_privilege('app_user','public.projection_outbox','DELETE')::int" "0"\ncheck "RLS activado en toda tabla operacional con tenant_id" \\n  "SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND EXISTS (SELECT 1 FROM information_schema.columns col WHERE col.table_schema=n.nspname AND col.table_name=c.relname AND col.column_name='tenant_id') AND c.relname NOT LIKE 'flyway_%' AND NOT c.relrowsecurity" "0"\nfor version in 17 18 19 20 21; do\n  check "Flyway V${version} registrada como exitosa" \\n    "SELECT count(*) FROM public.flyway_schema_history WHERE version='${version}' AND success" "1"\ndone\ncheck "Esquema camunda existe" \\n  "SELECT count(*) FROM information_schema.schemata WHERE schema_name='camunda'" "1"\ncheck "app_user no puede crear objetos en public" \\n  "SELECT has_schema_privilege('app_user','public','CREATE')::int" "0"\ncheck "app_user tiene USAGE en camunda" \\n  "SELECT has_schema_privilege('app_user','camunda','USAGE')::int" "1"\ncheck "RLS y FORCE RLS en payment_approval_decision" \\n  "SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='payment_approval_decision' AND c.relrowsecurity AND c.relforcerowsecurity" "1"\ncheck "outbox_worker existe, LOGIN y sin SUPERUSER/BYPASSRLS" \\n  "SELECT count(*) FROM pg_roles WHERE rolname='outbox_worker' AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb" "1"\ncheck "Outbox global claim no concedido a app_user (least-privilege)" \\n  "SELECT has_function_privilege('app_user','public.claim_projection_outbox(integer)','EXECUTE')::int" "0"\ncheck "Outbox global claim concedido al worker dedicado" \\n  "SELECT has_function_privilege('outbox_worker','public.claim_projection_outbox(integer)','EXECUTE')::int" "1"\n\nfor table in compliance_subcontractor_head invoice payment_application payment three_way_match_result safety_incident rfi change_order submittal permit_application bid_package bid contract; do\n  check "tabla public.$table existe" \\n    "SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name='$table'" "1"\ndone\n\ncheck "BPMN paymentApprovalProcess desplegado en camunda" \\n  "SELECT count(*) FROM camunda.act_re_procdef WHERE key_='paymentApprovalProcess'" "1"\ncheck "BPMN rfiProcess desplegado en camunda" \\n  "SELECT count(*) FROM camunda.act_re_procdef WHERE key_='rfiProcess'" "1"\ncheck "DMN complianceVigente desplegada en camunda" \\n  "SELECT count(*) FROM camunda.act_re_decision_def WHERE key_='complianceVigente'" "1"\ncheck "DMN nivelAprobacionPago desplegada en camunda" \\n  "SELECT count(*) FROM camunda.act_re_decision_def WHERE key_='nivelAprobacionPago'" "1"\n\nif (( fail )); then\n  echo "RESULT: BLOCKED — uno o más gates de release fallaron."\n  exit 1\nfi\necho "RESULT: gates verificables de BD pasaron. Esto no sustituye build ni pruebas de integración."